export const BUNDLE_SCHEMA = `
  CREATE TABLE project (
    singleton INTEGER PRIMARY KEY CHECK(singleton = 1),
    id TEXT NOT NULL UNIQUE, name TEXT NOT NULL,
    created_at TEXT NOT NULL, updated_at TEXT NOT NULL
  );
  CREATE TABLE sessions (
    id TEXT PRIMARY KEY, initial_prompt TEXT NOT NULL,
    project_kind TEXT NOT NULL, source_workspace_id TEXT,
    created_at TEXT NOT NULL, context_path TEXT, details_json TEXT NOT NULL
  );
  CREATE TABLE batches (
    id TEXT NOT NULL, session_id TEXT NOT NULL REFERENCES sessions(id),
    request_id TEXT, label TEXT, instruction TEXT, created_at TEXT NOT NULL,
    context_path TEXT, PRIMARY KEY(session_id, id)
  );
  CREATE TABLE snapshots (
    id TEXT PRIMARY KEY, git_ref TEXT NOT NULL, commit_sha TEXT NOT NULL,
    tree_sha TEXT, created_at TEXT NOT NULL
  );
  CREATE TABLE variants (
    session_id TEXT NOT NULL REFERENCES sessions(id), variant_id TEXT NOT NULL,
    batch_id TEXT NOT NULL, label TEXT NOT NULL, brief TEXT NOT NULL,
    status TEXT NOT NULL, created_at TEXT NOT NULL, status_changed_at TEXT NOT NULL,
    snapshot_id TEXT REFERENCES snapshots(id), base_snapshot_id TEXT REFERENCES snapshots(id),
    parent_snapshot_id TEXT REFERENCES snapshots(id),
    parent_session_id TEXT, parent_variant_id TEXT,
    changed_files_count INTEGER NOT NULL, artifact_path TEXT, details_json TEXT NOT NULL,
    PRIMARY KEY(session_id, variant_id),
    FOREIGN KEY(session_id, batch_id) REFERENCES batches(session_id, id)
  );
  CREATE INDEX variants_created_at ON variants(created_at DESC);
  CREATE INDEX variants_status ON variants(status);
  CREATE TABLE presentation (
    key TEXT PRIMARY KEY, value_json TEXT NOT NULL, updated_at TEXT NOT NULL
  );
`;

export const REGISTRY_SCHEMA = `
  CREATE TABLE projects (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    created_at TEXT NOT NULL,
    last_opened_at TEXT NOT NULL,
    storage_kind TEXT NOT NULL DEFAULT 'project' CHECK(storage_kind IN ('project', 'bundle')),
    source_fingerprint TEXT,
    removed_at TEXT,
    pinned_at TEXT
  );
  CREATE TABLE workspaces (
    id TEXT PRIMARY KEY,
    project_id TEXT NOT NULL UNIQUE REFERENCES projects(id),
    canonical_path TEXT NOT NULL UNIQUE
  );
  CREATE TABLE history_roots (
    canonical_path TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id)
  );
`;

export const COORDINATOR_SCHEMA =
  'CREATE TABLE coordinator(singleton INTEGER PRIMARY KEY CHECK(singleton=1), pid INTEGER NOT NULL, token TEXT NOT NULL, port INTEGER)';

export const REGISTRY_MIGRATIONS = [
  'ALTER TABLE projects ADD COLUMN removed_at TEXT',
  'ALTER TABLE projects ADD COLUMN pinned_at TEXT',
] as const;

export const PROJECT_RUNTIME_SCHEMA = `
  CREATE TABLE project_runtime (
    singleton INTEGER PRIMARY KEY CHECK(singleton = 1),
    pid INTEGER NOT NULL CHECK(pid > 0),
    token TEXT NOT NULL,
    phase TEXT NOT NULL CHECK(phase IN ('active', 'starting', 'retiring'))
  );
`;

export const BROWSER_AUTHORIZATION_SCHEMA = `
  CREATE TABLE browser_authority (
    singleton INTEGER PRIMARY KEY CHECK(singleton = 1),
    account_id TEXT, generation TEXT NOT NULL,
    operation_id TEXT, phase TEXT NOT NULL CHECK(phase IN ('ready', 'changing'))
  );
  CREATE TABLE browser_credentials (
    digest TEXT PRIMARY KEY, scope TEXT NOT NULL,
    account_id TEXT, generation TEXT NOT NULL,
    kind TEXT NOT NULL CHECK(kind IN ('session', 'launch')),
    expires_at INTEGER NOT NULL
  );
`;
